---InitData 初始化数据
---@param disablePoints table 禁用的点
---@param line number 行
---@param column number 列
---@param type number 地图类型
function AStarMgr:InitData(disablePoints, line, column, type)
    line = checkNumber(line)
    column = checkNumber(column)
    disablePoints = checkTable(disablePoints)
    if column < 1 or line < 1 then
        return
    end
    self._diablePoints = disablePoints
    self._mapType = checkNumber(type)
    self._maxLine = line
    self._maxColumn = column

    self._allPoint = {}
    --先画行
    for i = 1, line do
        self._allPoint[i] = {}
        for j = 1, column do
            local vo = AStarVo.New()
            vo:FillVo(i, j, self:IsDisablePoint(i, j))
            self._allPoint[i][j] = vo
        end
    end
end

---FindPath 寻找
---@param startPoint table {line = 1, column = 1}
---@param endPoint table 
function AStarMgr:FindPath(startPoint, endPoint)
    if not startPoint or not endPoint then
        return {}
    end

    startPoint = checkTable(startPoint)
    endPoint = checkTable(endPoint)

    self._endPoint = endPoint
    self._startPoint = startPoint
    self._openPoints = {}
    self._closePoints = {}

    if self:IsDisablePoint(self._endPoint._line, self._endPoint._column) then
        --printError("目标点为障碍物")
        return
    end

    local num = 1
    table.insert(self._openPoints, clone(self._startPoint))
    local curPoint = self:GetMinFPoint()
    while curPoint do
        self:CheckBasePoint(curPoint)
        if table.count(self._openPoints) < 1 or self:IsInOpenPoints(self._endPoint) then
            break
        end
        curPoint = self:GetMinFPoint()

        num = num+ 1 
        if num > 500 then
            --printError("寻路超时")
            break
        end
    end

    local tPoint = self:GetOpenListPoint(self._endPoint)
    if isNull(tPoint) then
        --printError("寻路失败")
        return {}
    end
    
    num = 0
    local t = {}
    local fatherPoint = tPoint:GetFatherPoint()
    table.insert(t, tPoint)
    while fatherPoint do
        table.insert(t, fatherPoint)
        fatherPoint = fatherPoint:GetFatherPoint()
    
        num = num+ 1 
        if num > 1000 then
            --printError("寻路超时")
            break
        end
    end
    return t
end

---CheckBasePoint 检查该点附近的
---@param pointVo table AStarVo
function AStarMgr:CheckBasePoint(pointVo)
    if not pointVo then
        return    
    end

    if self._mapType == MAPTYPE.SQUARE then
        self:CheckSquarePoint(pointVo)
    elseif self._mapType == MAPTYPE.SEXANGLE then
        self:CheckSexanglePoint(pointVo)
    end
end

--正方形
function AStarMgr:CheckSquarePoint(pointVo)
    local l, c = pointVo:GetLineAndColumn()
    --行
    for i = l - 1, l + 1 do
        if i >= 1 and i <= self._maxLine then
            --列
            for j = c - 1, c + 1 do
                if j >= 1 and j <= self._maxColumn and ((i == l) or (j == c)) then
                    if not self:IsDisablePoint(i, j) and not self:IsInClosePoints(i, j) then --g改这里 (i == l and j ~= c) then
                        if i == l and j == c then
                            --如果是相同的点 不做判断
                        else
                            local vo = AStarVo.New()
                            vo:FillVo(i, j)
                            self:RefreshPointGH(pointVo, vo)

                            self:AddOpenListPoint(vo)
                            --table.insert(self._openPoints, vo)
                        end
                    end     
                end
            end
        end
    end
    self:RemoveOpenListPoint(pointVo)
    table.insert(self._closePoints, pointVo)
end

--正六边形
function AStarMgr:CheckSexanglePoint(pointVo)

end

---RefreshPointGH 刷新点的gh值
---@param fPoint table 
---@param tPoint table 
function AStarMgr:RefreshPointGH(fPoint, tPoint)
    if not fPoint or not tPoint then
        return
    end
    local fg, fh = fPoint:GetGH()
    local tg, th = tPoint:GetGH()
    local _g = self:GetG(fPoint, tPoint)
    if isNull(tPoint:GetFatherPoint()) then
        tPoint:FillFatherPoint(fPoint)
        tPoint:FillGH(_g, self:GetPointH(tPoint))
    elseif _g + fg < tg then
        tPoint:FillFatherPoint(fPoint)
        tPoint:FillGH(_g + fg, self:GetPointH(tPoint))
    end
end

---RemoveOpenListPoint 删除一个节点
---@param point table 
function AStarMgr:RemoveOpenListPoint(point)
    if not self._openPoints or not point then
        return
    end
    for i = 1, table.count(self._openPoints) do 
        local l, c = point:GetLineAndColumn()
        local _l, _c = self._openPoints[i]:GetLineAndColumn()
        if _l == l and _c == c then
            table.remove(self._openPoints, i)
            return
        end
    end
end

---AddOpenListPoint 增加一个节点
---@param point table 
function AStarMgr:AddOpenListPoint(point)
    if not self._openPoints or not point then
        return
    end

    table.insert(self._openPoints, point)
end

---GetOpenListPoint 获取一个节点
---@param point table 
function AStarMgr:GetOpenListPoint(point)
    if not self._openPoints or not point then
        return nil
    end
    local l, c = point:GetLineAndColumn()
    for i = 1, table.count(self._openPoints) do 
        local _l, _c = self._openPoints[i]:GetLineAndColumn()
        if _l == l and _c == c then
            return self._openPoints[i]
        end
    end
    return nil
end

---GetPoint 获取一个点
---@param l number 行
---@param c number 列
function AStarMgr:GetPoint(l, c)
    if not self._allPoint or table.count(self._allPoint) < 1 then
        return nil 
    end
    l = checkNumber(l)
    c = checkNumber(c)
    
    for k, v in pairs(self._allPoint) do
        local _l, _c = v:GetLineAndColumn()
        if checkNumber(_l) == l or checkNumber(_c) == c then
            return v        
        end 
    end
    return nil
end 

---GetMinPoint 获取openlist中f值最小的
function AStarMgr:GetMinFPoint()
    if not self._openPoints then
        return nil
    end
    local pointVo
    for k, vo in pairs(self._openPoints) do
        if pointVo then
            local f1 = vo:GetF()
            local f2 = pointVo:GetF()
            if f1 < f2 then
                pointVo = vo
            end
        else
            pointVo = vo            
        end
    end
    return pointVo
end

