function AStarMgr:GetG(fPoint, tPoint)
    local lf, cf = fPoint:GetLineAndColumn()
    local lt, ct = tPoint:GetLineAndColumn()

    if self._mapType == MAPTYPE.SQUARE then
        if lf == lt or cf == ct then
            return 10
        else
            return 14
        end
    elseif self._mapType == MAPTYPE.SEXANGLE then
    end   
    return 0
end

---GetPointH 获取改点的h值
---@param point table 
function AStarMgr:GetPointH(point)
    if not point or not self._endPoint then
        return 0
    end
    local l1, c1 = self._endPoint:GetLineAndColumn()
    local l2, c2 = point:GetLineAndColumn()
    return (math.abs(l1 - l2) + math.abs(c1 - c2)) * 10
end

---IsSamePoint 是否是相同的点
---@param point1 table 
---@param point2 table 
function AStarMgr:IsSamePoint(point1, point2)
    if not point1 or not point2 then
        return false
    end
    local l1, c1 = point1:GetLineAndColumn()
    local l2, c2 = point1:GetLineAndColumn()
    return (l1 == l2 and c1 == c2)
end

---IsInClosePoints 是否是已经检查过的点
---@param l number 行
---@param c number 列
function AStarMgr:IsInClosePoints(l, c)
    if not self._closePoints or table.count(self._closePoints) < 1 then
        return false
    end
    l = checkNumber(l)
    c = checkNumber(c)
    for k, v in pairs(self._closePoints) do
        local _l, _c = v:GetLineAndColumn()
        if _l == l and _c == c then
            return true
        end
    end
    return false
end

---IsInOpenPoints 是否
---@param point table 
function AStarMgr:IsInOpenPoints(point)
    if not self._openPoints or not point then
        return false
    end
    local l, c = point:GetLineAndColumn()
    for i = 1, table.count(self._openPoints) do 
        local _l, _c = self._openPoints[i]:GetLineAndColumn()
        if _l == l and _c == c then
            return true
        end
    end
    return false
end

---IsDisablePoint 是否是禁用的点
---@param l number 行
---@param c number 列
function AStarMgr:IsDisablePoint(l, c)
    if not self._diablePoints or table.count(self._diablePoints) < 1 then
        return false
    end

    l = checkString(l)
    c = checkNumber(c)
    local t = self._diablePoints[l]
    if not t or table.count(t) < 1 then
        return false
    end
    for k, v in pairs(t) do
        if checkNumber(v) == c then
            return true
        end
    end
    return false
end

--刷新禁用点
function AStarMgr:RefreshDisablePoints(t)
    if not t then
        return
    end

    self._diablePoints = clone(t)
end

